#' Style an Individual Gene or Label
#'
#' Adds or updates an override for one element, without replacing the styles of
#' other elements. Use this in an editor and in the R code generated by it.
#'
#' @param GC_chart A GC chart object.
#' @param component The component to edit: `"genes"` or `"labels"`.
#' @param row_id The gene's `rowID` in `GC_chart$x$data`, also returned in
#'   `input$<outputId>_select$data$rowID` and double-click event data.
#' @param ... Named element options, using JavaScript names, e.g. `fill`,
#'   `stroke`, `strokeWidth`, `marker`, `markerSize`, `fontSize`, `dx`, `dy`
#'   or `rotate`. Labels also accept `text` to override their displayed text.
#' @param reset Logical, remove this element's override instead of updating it.
#'
#' @details Overrides match the row ID rather than the element's drawing index,
#'   so sorting, reverse clusters, resize and repeated gene names do not change
#'   their target. Row IDs are assigned by [GC_chart()] after filtering missing
#'   coordinates. Reproducing an edit requires the same input rows in the same
#'   order; replacing or reordering the input data requires remapping edits.
#'   These overrides take precedence over group styles and index-based styles.
#'   Reset removes the row-specific override, restoring underlying styles.
#'   Call this after the component's normal configuration.
#'
#' @return The chart with the element override updated.
#' @examples
#' genes <- data.frame(start = c(90, 10), end = c(130, 50), name = c("a", "a"))
#' GC_chart(genes) %>%
#'   GC_labels("name") %>%
#'   GC_element_style("genes", row_id = 1, fill = "red", marker = "box") %>%
#'   GC_element_style("labels", row_id = 1, text = "Edited", fontSize = "16px")
#' @export
GC_element_style <- function(GC_chart, component = c("genes", "labels"),
                             row_id, ..., reset = FALSE) {
  component <- match.arg(component)
  if (!is.numeric(row_id) || length(row_id) != 1 || is.na(row_id) ||
      !is.finite(row_id) || !row_id %in% GC_chart$x$data$rowID) {
    stop("'row_id' must identify one row in the chart's data.")
  }
  if (!is.logical(reset) || length(reset) != 1 || is.na(reset)) {
    stop("'reset' must be TRUE or FALSE.")
  }
  style <- list(...)
  if (length(style) && (is.null(names(style)) || anyNA(names(style)) ||
                        any(!nzchar(names(style))) || anyDuplicated(names(style)))) {
    stop("Element options must have unique, nonempty names.")
  }
  if (any(names(style) %in% c("index", "rowID"))) {
    stop("Use 'row_id' to identify the element, not 'index' or 'rowID'.")
  }
  if (reset && length(style)) stop("Do not supply element options with 'reset = TRUE'.")

  for (cluster in names(GC_chart$x$series)) {
    series <- GC_chart$x$series[[cluster]]
    if (!row_id %in% series$data$rowID) next
    items <- series[[component]]$itemStyle
    matched <- vapply(items, function(item) identical(as.numeric(item$rowID),
                                                     as.numeric(row_id)), logical(1))
    previous <- if (any(matched)) items[[which(matched)[1]]] else list()
    items <- items[!matched]
    if (!reset) {
      override <- utils::modifyList(previous, style)
      override$rowID <- row_id
      items <- c(items, list(override))
    }
    GC_chart$x$series[[cluster]][[component]]$itemStyle <- unname(items)
  }
  GC_chart
}
